def lineprop(inp, linecol, bgcol, connectivity=4):
  # CC regions outside line; their dominant non-bg color if any
  other=inp!=linecol; rooms0,n0=label(other)
  inf={}
  for rid in range(1,n0+1):
    vals,cnts=np.unique(inp[rooms0==rid],return_counts=True)
    fg={int(v):int(n) for v,n in zip(vals,cnts) if v!=bgcol}
    inf[rid]=max(fg,key=fg.get) if fg else None
  lin=inp==linecol
  deg0=convolve(lin.astype(int),cross,mode='constant',cval=0)
  branch0=lin&(deg0>=3); straight=lin&~branch0
  lbl0,nn=label(straight)
  out0=inp.copy(); compcs=defaultdict(Counter); brcs={}
  # directly adjacent line cells to foreground regions, sources target room mode
  for r,c in np.argwhere(lin):
   cs=[]
   for rr,cc in [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]:
    if 0<=rr<inp.shape[0] and 0<=cc<inp.shape[1] and rooms0[rr,cc]>0 and inf[int(rooms0[rr,cc])] is not None:
     cs.append(inf[int(rooms0[rr,cc])])
   if not cs: continue
   col=Counter(cs).most_common(1)[0][0]
   if branch0[r,c]:
    brcs[(r,c)]=col
    for rr,cc in [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]:
     if 0<=rr<inp.shape[0] and 0<=cc<inp.shape[1] and straight[rr,cc]: compcs[int(lbl0[rr,cc])][col]+=1
   else: compcs[int(lbl0[r,c])][col]+=1
  for i,ccs in compcs.items():
   col=ccs.most_common(1)[0][0]; out0[lbl0==i]=col
  for p,col in brcs.items():out0[p]=col
  return out0, (rooms0,inf,branch0,lbl0,compcs,brcs)
