from collections import deque

def graphprop(inp,linecol,bgcol):
  rooms,nr0=label(inp!=linecol)
  roommode={}
  for rid in range(1,nr0+1):
    vals,cnts=np.unique(inp[rooms==rid],return_counts=True)
    fg={int(v):int(n) for v,n in zip(vals,cnts) if v!=bgcol}
    roommode[rid]=max(fg,key=fg.get) if fg else None
  line=inp==linecol
  seeds={}
  for r,c in np.argwhere(line):
    cols=[]
    for rr,cc in [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]:
      if 0<=rr<inp.shape[0] and 0<=cc<inp.shape[1] and rooms[rr,cc]>0:
       m=roommode[int(rooms[rr,cc])]
       if m is not None: cols.append(m)
    if cols:
      seeds[(r,c)]=Counter(cols).most_common(1)[0][0]
  # distance source colors along line graph BFS per color
  cols=set(seeds.values())
  dists={cl:np.full(inp.shape,999,int) for cl in cols}
  for cl in cols:
    q=deque()
    for p,v in seeds.items():
      if v==cl: dists[cl][p]=0;q.append(p)
    while q:
      r,c=q.popleft()
      for rr,cc in [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]:
       if 0<=rr<inp.shape[0] and 0<=cc<inp.shape[1] and line[rr,cc] and dists[cl][rr,cc]>dists[cl][r,c]+1:
        dists[cl][rr,cc]=dists[cl][r,c]+1;q.append((rr,cc))
  out=inp.copy()
  for r,c in np.argwhere(line):
    vals=[d[r,c] for d in dists.values()]; m=min(vals); winners=[cl for cl,d in dists.items() if d[r,c]==m]
    if len(winners)==1:out[r,c]=winners[0]
  return out,seeds,dists
